-- Esquema base de Motiq en Postgres.
-- Generado por scripts/convertir-volcado-a-postgres.js a partir del volcado MySQL
-- (db/sasstaller.sql). Desde acá el esquema evoluciona con migraciones nuevas en esta
-- misma carpeta (0002_..., 0003_...); este archivo no se edita a mano.

CREATE EXTENSION IF NOT EXISTS citext;

-- Reemplazo de ON UPDATE CURRENT_TIMESTAMP de MySQL.
CREATE OR REPLACE FUNCTION motiq_tocar_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE "avisos_plataforma" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "mensaje" varchar(500) NOT NULL,
  "tipo" varchar(13) NOT NULL DEFAULT 'info' CHECK ("tipo" IN ('info','mantenimiento','urgente')),
  "activo" smallint NOT NULL DEFAULT 1,
  "admin_id" integer,
  "admin_email" citext CHECK (char_length("admin_email") <= 150),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "vence_el" timestamptz,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_avisos_activo" ON "avisos_plataforma" ("activo", "created_at");
CREATE TRIGGER "trg_avisos_plataforma_updated_at" BEFORE UPDATE ON "avisos_plataforma"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "citas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "cliente_id" integer NOT NULL,
  "vehiculo_id" integer,
  "usuario_id" integer,
  "tecnico_id" integer,
  "sucursal_id" integer,
  "fecha" date NOT NULL,
  "hora" time NOT NULL,
  "motivo" text NOT NULL,
  "tipo_servicio" varchar(100),
  "estado" varchar(16) NOT NULL DEFAULT 'agendado' CHECK ("estado" IN ('agendado','en_revision','en_mantenimiento','listo','entregado','cancelado')),
  "monto" numeric(10,2) DEFAULT 0.00,
  "calificacion" smallint,
  "comentario_satisfaccion" text,
  "fecha_inicio" timestamptz,
  "fecha_fin" timestamptz,
  "hora_llegada" timestamptz,
  "orden_id" integer,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "confirmada_cliente" smallint DEFAULT 0,
  "fecha_listo" timestamptz,
  "recordatorio_enviado" smallint NOT NULL DEFAULT 0,
  "no_show" smallint NOT NULL DEFAULT 0,
  "fecha_cancelacion" timestamptz,
  "tenant_id" integer NOT NULL,
  "es_ejemplo" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_citas_orden" ON "citas" ("orden_id");
CREATE INDEX "idx_citas_sucursal_fecha_hora" ON "citas" ("sucursal_id", "fecha", "hora");
CREATE INDEX "idx_citas_cliente_id" ON "citas" ("cliente_id");
CREATE INDEX "idx_citas_usuario_id" ON "citas" ("usuario_id");
CREATE INDEX "idx_citas_fk_citas_tecnico" ON "citas" ("tecnico_id");
CREATE INDEX "idx_citas_tenant" ON "citas" ("tenant_id");
CREATE INDEX "idx_citas_tenant_fecha" ON "citas" ("tenant_id", "fecha", "hora");
CREATE INDEX "idx_citas_vehiculo" ON "citas" ("vehiculo_id");
CREATE TRIGGER "trg_citas_updated_at" BEFORE UPDATE ON "citas"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "clientes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(100) NOT NULL,
  "apellido" varchar(100) NOT NULL,
  "telefono" varchar(20) NOT NULL,
  "email" citext CHECK (char_length("email") <= 100),
  "cedula" varchar(20),
  "direccion" text,
  "password_hash" varchar(255),
  "visitas" integer DEFAULT 0,
  "cortesia_disponible" smallint DEFAULT 0,
  "notif_avances" smallint NOT NULL DEFAULT 1,
  "notif_recordatorios" smallint NOT NULL DEFAULT 1,
  "activo" smallint DEFAULT 1,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "foto" text,
  "email_verificado" smallint NOT NULL DEFAULT 1,
  "email_pendiente" citext CHECK (char_length("email_pendiente") <= 150),
  "tenant_id" integer NOT NULL,
  "es_ejemplo" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_clientes_tenant" ON "clientes" ("tenant_id");
CREATE INDEX "idx_clientes_tenant_nombre" ON "clientes" ("tenant_id", "activo", "nombre", "apellido");
CREATE TRIGGER "trg_clientes_updated_at" BEFORE UPDATE ON "clientes"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "configuracion" (
  "id" smallint NOT NULL,
  "nombre_taller" varchar(150),
  "telefono" varchar(40),
  "email" citext CHECK (char_length("email") <= 120),
  "direccion" varchar(200),
  "logo" text,
  "max_citas_hora" integer DEFAULT 2,
  "dias_anticipacion" integer DEFAULT 30,
  "duracion_cita_min" integer DEFAULT 90,
  "horarios" jsonb,
  "notif_estado" smallint DEFAULT 1,
  "notif_recordatorio" smallint DEFAULT 1,
  "notif_cotizacion" smallint DEFAULT 1,
  "notif_email_entrega" smallint DEFAULT 0,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "cancelacion_horas_min" integer DEFAULT 2,
  "visitas_para_cortesia" integer DEFAULT 7,
  "zona_horaria_offset" integer DEFAULT -6,
  "garantia_dias" integer DEFAULT 30,
  "metodos_pago" jsonb,
  "tenant_id" integer NOT NULL,
  "tipos_vehiculo" jsonb,
  "color_primario" varchar(7),
  "arranque_oculto" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("tenant_id", "id")
);
CREATE INDEX "idx_configuracion_tenant" ON "configuracion" ("tenant_id");
COMMENT ON COLUMN "configuracion"."tipos_vehiculo" IS 'Tipos que atiende el taller, ej. ["moto","auto"]';
COMMENT ON COLUMN "configuracion"."color_primario" IS 'Color de marca del taller en hex (#rrggbb). NULL = por defecto';
CREATE TRIGGER "trg_configuracion_updated_at" BEFORE UPDATE ON "configuracion"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

