CREATE TABLE "ordenes_trabajo" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "numero_orden" varchar(20) NOT NULL,
  "vehiculo_id" integer NOT NULL,
  "cliente_id" integer NOT NULL,
  "sucursal_id" integer,
  "recepcionista_id" integer,
  "tecnico_id" integer,
  "estado" varchar(20) NOT NULL DEFAULT 'recepcion' CHECK ("estado" IN ('recepcion','diagnostico','esperando_aprobacion','esperando_repuestos','en_reparacion','lista_entrega','entregada','cancelada')),
  "problema_reportado" text NOT NULL,
  "kilometraje_ingreso" integer,
  "nivel_combustible" varchar(12) DEFAULT 'cuarto' CHECK ("nivel_combustible" IN ('vacio','cuarto','mitad','tres_cuartos','lleno')),
  "accesorios_entregados" text,
  "estado_fisico" text,
  "prioridad" varchar(10) DEFAULT 'normal' CHECK ("prioridad" IN ('normal','urgente','emergencia','garantia')),
  "categoria" varchar(11) DEFAULT 'diagnostico' CHECK ("categoria" IN ('rapido','garantia','emergencia','diagnostico','preventivo','mayor')),
  "diagnostico" text,
  "tiempo_estimado_horas" numeric(5,2),
  "costo_mano_obra" numeric(10,2) DEFAULT 0.00,
  "costo_repuestos" numeric(10,2) DEFAULT 0.00,
  "descuento" numeric(10,2) DEFAULT 0.00,
  "aprobado_por_cliente" smallint DEFAULT 0,
  "aprobacion_cliente" varchar(9) NOT NULL DEFAULT 'pendiente' CHECK ("aprobacion_cliente" IN ('pendiente','aprobado','rechazado')),
  "motivo_rechazo" text,
  "fecha_aprobacion" timestamptz,
  "fecha_ingreso" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "fecha_estimada_entrega" date,
  "fecha_entrega_real" timestamptz,
  "metodo_pago" varchar(13) CHECK ("metodo_pago" IN ('efectivo','sinpe','tarjeta','transferencia')),
  "garantia_dias" integer DEFAULT 0,
  "observaciones_finales" text,
  "calificacion" smallint,
  "comentario_satisfaccion" text,
  "visita_contada" smallint DEFAULT 0,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" integer NOT NULL,
  "es_ejemplo" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_ordenes_trabajo_tenant" UNIQUE ("tenant_id", "numero_orden")
