CREATE INDEX "idx_ordenes_trabajo_fk_ordenes_sucursal" ON "ordenes_trabajo" ("sucursal_id");
CREATE INDEX "idx_ordenes_trabajo_tenant" ON "ordenes_trabajo" ("tenant_id");
