  PRIMARY KEY ("id")
);
CREATE INDEX "idx_promos_tenant" ON "promos" ("tenant_id");
CREATE TRIGGER "trg_promos_updated_at" BEFORE UPDATE ON "promos"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "recompensas_canjeadas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "cliente_id" integer NOT NULL,
  "orden_id" integer,
  "aplicado_por" integer,
  "descripcion" varchar(150) NOT NULL DEFAULT 'Servicio de cortesía',
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" integer NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_rc_cliente" ON "recompensas_canjeadas" ("cliente_id");
CREATE INDEX "idx_recompensas_canjeadas_aplicado_por" ON "recompensas_canjeadas" ("aplicado_por");
CREATE INDEX "idx_recompensas_canjeadas_tenant" ON "recompensas_canjeadas" ("tenant_id");

CREATE TABLE "reportes_falla" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer,
  "tenant_nombre" varchar(150),
  "tenant_slug" varchar(120),
  "usuario_id" integer,
  "usuario_nombre" varchar(120),
  "usuario_email" citext CHECK (char_length("usuario_email") <= 150),
  "usuario_rol" varchar(20),
  "descripcion" text NOT NULL,
  "pantalla" varchar(200),
  "estado" varchar(10) NOT NULL DEFAULT 'nuevo' CHECK ("estado" IN ('nuevo','revisando','resuelto','descartado')),
  "nota_interna" varchar(500),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_reportes_estado" ON "reportes_falla" ("estado", "created_at");
CREATE TRIGGER "trg_reportes_falla_updated_at" BEFORE UPDATE ON "reportes_falla"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "servicios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(120) NOT NULL,
  "activo" smallint NOT NULL DEFAULT 1,
  "orden" integer DEFAULT 0,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" integer NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_servicios_tenant" UNIQUE ("tenant_id", "nombre")
);
CREATE INDEX "idx_servicios_tenant" ON "servicios" ("tenant_id");
CREATE TRIGGER "trg_servicios_updated_at" BEFORE UPDATE ON "servicios"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "sucursales" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(100) NOT NULL,
  "direccion" varchar(200),
  "telefono" varchar(40),
  "activa" smallint DEFAULT 1,
  "orden" integer DEFAULT 0,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" integer NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_sucursales_tenant" ON "sucursales" ("tenant_id");
CREATE TRIGGER "trg_sucursales_updated_at" BEFORE UPDATE ON "sucursales"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "tareas_mecanico" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tecnico_id" integer NOT NULL,
  "titulo" varchar(150) NOT NULL,
  "detalle" varchar(300),
  "prioridad" varchar(7) NOT NULL DEFAULT 'normal' CHECK ("prioridad" IN ('baja','normal','alta','urgente')),
  "hecha" smallint DEFAULT 0,
  "asignado_por" integer,
  "vence" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" integer NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_tarea_tecnico" ON "tareas_mecanico" ("tecnico_id");
CREATE INDEX "idx_tareas_mecanico_asignado_por" ON "tareas_mecanico" ("asignado_por");
CREATE INDEX "idx_tareas_mecanico_tenant" ON "tareas_mecanico" ("tenant_id");

CREATE TABLE "tenants" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(150) NOT NULL,
  "slug" varchar(60) NOT NULL,
  "plan" varchar(30) NOT NULL DEFAULT 'trial',
  "estado" varchar(20) NOT NULL DEFAULT 'activo',
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "motivo_estado" varchar(200),
  "trial_hasta" date,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_tenant_slug" UNIQUE ("slug")
);
CREATE INDEX "idx_tenants_estado" ON "tenants" ("estado");
COMMENT ON COLUMN "tenants"."slug" IS 'subdominio/identificador publico';
COMMENT ON COLUMN "tenants"."estado" IS 'activo|suspendido|cancelado';
COMMENT ON COLUMN "tenants"."motivo_estado" IS 'Por que se suspendio o reactivo (lo escribe el admin de Motiq)';
CREATE TRIGGER "trg_tenants_updated_at" BEFORE UPDATE ON "tenants"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "usuario_verify_codes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "code_hash" varchar(255) NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "used" smallint NOT NULL DEFAULT 0,
  "attempts" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_uvc_usuario" ON "usuario_verify_codes" ("usuario_id");
CREATE INDEX "idx_uvc_tenant" ON "usuario_verify_codes" ("tenant_id");

CREATE TABLE "usuarios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(100) NOT NULL,
  "email" citext NOT NULL CHECK (char_length("email") <= 100),
  "password_hash" varchar(255) NOT NULL,
  "rol" varchar(9) NOT NULL DEFAULT 'tecnico' CHECK ("rol" IN ('recepcion','tecnico','admin')),
  "telefono" varchar(20),
  "especialidades" varchar(300),
  "horario" varchar(200),
  "sucursal_id" integer,
  "activo" smallint DEFAULT 1,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "foto" text,
  "totp_secret" varchar(64),
  "totp_activado" smallint NOT NULL DEFAULT 0,
  "totp_backup" text,
  "totp_ultimo_contador" bigint,
  "tenant_id" integer NOT NULL,
  "email_verificado" smallint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_usuarios_tenant" UNIQUE ("tenant_id", "email")
);
CREATE INDEX "idx_usuarios_fk_usuarios_sucursal" ON "usuarios" ("sucursal_id");
CREATE INDEX "idx_usuarios_tenant" ON "usuarios" ("tenant_id");
CREATE TRIGGER "trg_usuarios_updated_at" BEFORE UPDATE ON "usuarios"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "vehiculos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "cliente_id" integer NOT NULL,
  "tipo" varchar(20) NOT NULL,
  "marca" varchar(50) NOT NULL,
  "modelo" varchar(100) NOT NULL,
  "anio" smallint,
  "placa" varchar(20),
  "color" varchar(50),
  "numero_motor" varchar(50),
  "numero_chasis" varchar(50),
  "kilometraje_actual" integer DEFAULT 0,
  "foto_url" varchar(500),
  "activa" smallint DEFAULT 1,
  "placa_norm" varchar(32) GENERATED ALWAYS AS (upper(replace(replace(placa,' ',''),'-',''))) STORED,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "foto" text,
  "tenant_id" integer NOT NULL,
  "atributos" jsonb,
  "es_ejemplo" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_vehiculos_tenant" UNIQUE ("tenant_id", "placa_norm")
);
CREATE INDEX "idx_vehiculos_cliente_id" ON "vehiculos" ("cliente_id");
CREATE INDEX "idx_vehiculos_tenant" ON "vehiculos" ("tenant_id");
CREATE INDEX "idx_vehiculos_tipo" ON "vehiculos" ("tenant_id", "tipo");
COMMENT ON COLUMN "vehiculos"."atributos" IS 'Campos propios del tipo (ver utils/tipos-vehiculo.js)';
CREATE TRIGGER "trg_vehiculos_updated_at" BEFORE UPDATE ON "vehiculos"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

CREATE TABLE "web_vitals" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
